/// One `.kateproject` file.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Project {
    pub name: String,
    /// The directory that holds the project file.
    pub base_dir: std::path::PathBuf,
    pub files: Vec<FileSource>,
    /// Regular expressions. A relative path that matches one is dropped.
    pub exclude_patterns: Vec<String>,
}

/// One entry of the `files` array.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum FileSource {
    /// `git: true`. The files that git tracks under `directory`.
    Git { directory: std::path::PathBuf, recursive: bool },
    /// A directory walk with name filters.
    Directory { directory: std::path::PathBuf, filters: Vec<String>, recursive: bool, hidden: bool, symlinks: bool },
    /// `list: [...]`. Explicit paths relative to `directory`.
    List { directory: std::path::PathBuf, paths: Vec<std::path::PathBuf> },
}

